const config = {
  supabaseUrl: 'https://dsqgaxwgtcbqgphsofav.supabase.co',
  coachId: '5c635d4d-c73a-44f7-a010-f444c3567dc7',
  coachEmail: 'coach@entropicoaching.dk',
  appUrl: 'https://app.entropicoaching.dk/?coach=inbox',
};

const missing = Object.entries(config)
  .filter(([, value]) => !value || value.startsWith('REPLACE_WITH_'))
  .map(([key]) => key);

if (missing.length) {
  throw new Error(`Coach Briefing configuration missing: ${missing.join(', ')}`);
}

return [{ json: config }];

const item = $input.first();
const data = item?.json;
const config = $('Configuration').first().json;
const fail = reason => {
  // Keep errors metadata-only: never append the response or field values.
  throw new Error(`Coach briefing contract invalid: ${reason}`);
};

if (!data || typeof data !== 'object' || Array.isArray(data)) {
  fail('response must be an object');
}
if (data.schema_version !== 1) {
  fail('unsupported schema version');
}
if (typeof data.generated_at !== 'string' || !Number.isFinite(Date.parse(data.generated_at))) {
  fail('generated_at missing or invalid');
}
if (String(data.coach_id || '') !== String(config.coachId || '')) {
  fail('coach identity mismatch');
}
for (const field of ['unread_messages', 'video_drafts', 'training_signals']) {
  if (!Array.isArray(data[field])) fail(`${field} must be an array`);
}

return [item];

const data = $input.first().json;
const config = $('Configuration').first().json;
const messages = Array.isArray(data.unread_messages) ? data.unread_messages : [];
const videos = Array.isArray(data.video_drafts) ? data.video_drafts : [];
const signals = Array.isArray(data.training_signals) ? data.training_signals : [];
const unreadCount = messages.reduce((sum, item) => sum + Number(item.unread_count || 0), 0);
const total = unreadCount + videos.length + signals.length;
const briefingDate = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Copenhagen', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());

// Returning no items ends the workflow: no empty morning email.
if (total === 0) return [];

const esc = (value) => String(value ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('\"', '&quot;')
  .replaceAll("'", '&#039;');
const when = (value) => value
  ? new Intl.DateTimeFormat('da-DK', { dateStyle: 'short', timeStyle: 'short', timeZone: 'Europe/Copenhagen' }).format(new Date(value))
  : '';
const section = (title, count, rows) => rows.length
  ? `<section style="margin:0 0 22px"><h2 style="font-size:17px;margin:0 0 8px;color:#edeae2">${esc(title)} <span style="color:#c8923a">${count}</span></h2>${rows.join('')}</section>`
  : '';
const row = (title, detail) => `<div style="padding:10px 0;border-top:1px solid #34342e"><div style="font-weight:650;color:#edeae2">${esc(title)}</div><div style="font-size:13px;line-height:1.5;color:#aaa79f;margin-top:2px">${esc(detail)}</div></div>`;

const messageRows = messages.map(item => row(
  item.athlete_name,
  `${item.unread_count} ulæst${Number(item.unread_count) === 1 ? '' : 'e'} · ${item.track === 'teknik' ? 'Teknik & løft' : 'Besked'} · senest ${when(item.latest_at)}`
));
const videoRows = videos.map(item => {
  const lift = [item.lift, item.variation].filter(Boolean).join(' · ') || 'Videoanalyse';
  const load = item.load_kg == null ? '' : ` · ${item.load_kg} kg`;
  const reps = item.reps_count == null ? '' : ` · ${item.reps_count} reps`;
  return row(item.athlete_name, `${lift}${load}${reps} · modtaget ${when(item.created_at)}`);
});
const signalRows = signals.map(item => row(
  item.headline || item.athlete_name,
  `${item.severity === 'alert' ? 'Kræver et kig' : 'Kontekst'} · ${item.detail || item.detector}`
));

const appUrl = config.appUrl.replace(/\/$/, '');
const subject = `Entropi Coach · ${total} ting kræver et kig`;
const html = `<div style="background:#141410;padding:28px 18px;font-family:Arial,sans-serif"><div style="max-width:620px;margin:auto;background:#1c1c18;border:1px solid #34342e;padding:24px"><div style="font-size:12px;letter-spacing:.13em;text-transform:uppercase;color:#c8923a;margin-bottom:8px">Entropi Coach</div><h1 style="font-size:24px;line-height:1.2;color:#edeae2;margin:0 0 8px">Din coach-indbakke</h1><p style="color:#aaa79f;margin:0 0 24px;line-height:1.5">Kun åbne handlinger. Ingen videofiler eller beskedindhold er sendt gennem n8n.</p>${section('Beskeder', unreadCount, messageRows)}${section('Videoanalyser', videos.length, videoRows)}${section('Træningssignaler', signals.length, signalRows)}<a href="${esc(appUrl)}" style="display:inline-block;background:#c8923a;color:#141410;text-decoration:none;font-weight:700;padding:11px 16px;border-radius:3px">Åbn coach-indbakken</a><p style="font-size:11px;color:#68665f;margin:22px 0 0">Automatisk morgenbriefing · Europe/Copenhagen</p></div></div>`;

const fingerprintData = {
  recipient: config.coachEmail,
  messages: messages.map(item => [item.athlete_id, item.track, item.unread_count, item.latest_at]),
  videos: videos.map(item => item.id),
  signals: signals.map(item => [item.athlete_id, item.detector, item.severity, item.metrics]),
};
const source = JSON.stringify(fingerprintData);
let hash = 2166136261;
for (let i = 0; i < source.length; i++) {
  hash ^= source.charCodeAt(i);
  hash = Math.imul(hash, 16777619);
}

return [{ json: { recipient: config.coachEmail, subject, html, total, briefingDate, digestHash: `v1-${(hash >>> 0).toString(16)}` } }];

const item = $input.first();
const state = $getWorkflowStaticData('global');
if (state.lastDeliveredDate === item.json.briefingDate) return [];
return [item];

const briefing = $('Build briefing').first().json;
const state = $getWorkflowStaticData('global');
state.lastDigestHash = briefing.digestHash;
state.lastDeliveredAt = new Date().toISOString();
state.lastDeliveredDate = briefing.briefingDate;
return [{ json: { delivered: true, deliveredAt: state.lastDeliveredAt, deliveredDate: state.lastDeliveredDate, digestHash: state.lastDigestHash, itemCount: briefing.total } }];

const data = $input.first().json;
const now = Date.now();
const messageAgeMs = 6 * 60 * 60 * 1000;
const videoAgeMs = 24 * 60 * 60 * 1000;

const isOlderThan = (value, ageMs) => {
  if (!value) return true;
  const timestamp = new Date(value).getTime();
  return !Number.isFinite(timestamp) || now - timestamp >= ageMs;
};

const messages = (Array.isArray(data.unread_messages) ? data.unread_messages : [])
  .filter(item => isOlderThan(item.latest_at, messageAgeMs));
const videos = (Array.isArray(data.video_drafts) ? data.video_drafts : [])
  .filter(item => isOlderThan(item.created_at, videoAgeMs));
const signals = (Array.isArray(data.training_signals) ? data.training_signals : [])
  .filter(item => item.severity === 'alert');

// The app is the primary inbox. Email is only a safety net when an
// important or old item is still unresolved.
if (messages.length === 0 && videos.length === 0 && signals.length === 0) return [];

return [{
  json: {
    ...data,
    unread_messages: messages,
    video_drafts: videos,
    training_signals: signals,
    fallback_policy: {
      message_age_hours: 6,
      video_age_hours: 24,
      signal_severity: 'alert'
    }
  }
}];

const item = $input.first();
const json = item.json;

json.subject = String(json.subject || '')
  .replace('ting kræver et kig', 'uløste ting kræver stadig dit blik');
json.html = String(json.html || '')
  .replace('Din coach-indbakke', 'Noget kræver stadig dit blik')
  .replace(
    'Kun åbne handlinger. Ingen videofiler eller beskedindhold er sendt gennem n8n.',
    'Denne mail er kun en sikkerhedsline, fordi en vigtig eller ældre sag stadig står åben i appen. Ingen videofiler eller beskedindhold er sendt gennem n8n.'
  )
  .replace('Automatisk morgenbriefing', 'Automatisk sikkerhedsline');

return [item];
